"use Client"
import axios from "axios";
import { useState } from "react"

export default function Signup() {
    const [username, setUsername] = useState();
    const [password, setPassword] = useState();


    return <div className="flex flex-col flex-1 justify-center items-center">
        <div className="flex rounded flex-col gap-2  m-2 p-4 bg-amber-100 text-black">
            <label>username</label>
            <input className="border rounded p-2" type="text" placeholder="ex:abc@gmail.com"/>
            <label>password</label>
            <input className="border rounded p-2" type="password" placeholder="password"/>
        </div>
        <div>
            <button onClick={() => {
                axios.post('http://localhost:3000' , {
                    username,
                    password
                })
            }}>Sign Up</button>
        </div>
    </div>
}